<?php require_once __DIR__.'/../../includes/auth.php';require_login('admin');$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT COUNT(*) FROM bookings WHERE service_id=?');$s->execute([$id]);if($s->fetchColumn()>0){$s=$pdo->prepare("UPDATE services SET status='Inactive' WHERE id=?");$s->execute([$id]);flash('error','Service has booking history, so it was deactivated instead of deleted.');}else{$s=$pdo->prepare('DELETE FROM services WHERE id=?');$s->execute([$id]);log_activity('Service deletion','Deleted service '.$id);}redirect('admin/services/index.php');